```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

fis: a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An OWL ontology modelling securities, debt, equity, hybrid and derivative financial instruments as described in the supplied corpus." .

#################################################################
#  TOP-LEVEL FRAMEWORK
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32: any contract giving rise to a financial asset of one entity and a financial liability or equity instrument of another)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument whose value is determined directly by the markets; includes securities as well as loans and deposits." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument where both borrower and lender must agree to a transfer; not readily transferable." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset; readily transferable. Legal definition varies by jurisdiction." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:UnderlyingAsset ]
    )
  ] ;
  rdfs:comment "Instruments which derive their value from the value and characteristics of one or more underlying entities. NOTE: a majority of passages treat Derivative as a category of FinancialInstrument distinct from (cash) Security (cash vs derivative instrument split; 'derivatives are one of the three main categories of financial instruments, the other two being equity and debt'). This conflicts with the US SEC passage that categorises Derivatives as a sub-type of Security ('Securities can be broadly categorized into: Debt securities, Equity securities, Derivatives'); the majority view is modelled here." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CashInstrument fis:Derivative ) .

#################################################################
#  UNDERLYING ASSET
#################################################################

fis:UnderlyingAsset a owl:Class ;
  rdfs:label "underlying asset" ;
  rdfs:comment "The item (underlier) on which a derivative's value depends: a commodity, a financial instrument, a price index, a currency, or an interest rate." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:FinancialInstrument rdfs:subClassOf fis:UnderlyingAsset .

#################################################################
#  OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security (the issuer)." .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:UnderlyingAsset .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:UnderlyingAsset ; rdfs:range fis:Derivative .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Option .
fis:isEmbeddedOptionOf a owl:ObjectProperty ; owl:inverseOf fis:hasEmbeddedOption .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:EquitySecurity ;
  rdfs:comment "The equity security into which a convertible security may be converted." .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range owl:Thing .

fis:hasTranche a owl:ObjectProperty ;
  rdfs:domain fis:AssetBackedSecurity ; rdfs:range fis:Tranche .
fis:isTrancheOf a owl:ObjectProperty ; owl:inverseOf fis:hasTranche .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:CollateralArrangement ; rdfs:range owl:Thing .
fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range fis:Dividend .
fis:isDividendOf a owl:ObjectProperty ; owl:inverseOf fis:hasDividend .

#################################################################
#  DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer repays the nominal/principal amount." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "face value" ; rdfs:comment "Also called par value, nominal amount or principal amount." ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate the issuer pays to the holder." .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .

fis:hasSeniority a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ;
  rdfs:comment "E.g. senior or subordinated; determines priority in bankruptcy." .

fis:hasCallPrice a owl:DatatypeProperty ;
  rdfs:domain fis:CallableBond ; rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:date .

fis:hasDeliveryPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal .

fis:hasDebtFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasEquityFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasVotingRight a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range xsd:boolean .

fis:hasDividendRate a owl:DatatypeProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range xsd:decimal .

fis:isFungible a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "In a fungible security, all holdings of the security are treated identically and are interchangeable." .

fis:hasCurrencyDenomination a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasIndustrySector a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasMarketCapitalization a owl:DatatypeProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range xsd:decimal .

fis:hasTaxTreatment a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

#################################################################
#  SECURITY FORM (certificated / registration)
#################################################################

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "book-entry security" ;
  rdfs:comment "Non-certificated, electronic (dematerialised) or 'book entry only' security." .
fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "Entitles the holder to rights under the security merely by holding it; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each divided security constitutes a separate asset, legally distinct from each other security in the same issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset, each security being a fractional part of the undivided whole." .
[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

#################################################################
#  DEBT / EQUITY / HYBRID (core definitions)
#################################################################

fis:DebtSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDebtFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "The holder is typically entitled to payment of principal and interest; may be called debentures, bonds, deposits, notes or commercial paper." .

fis:EquitySecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasEquityFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "A share of equity interest in an entity such as capital stock; holder shares only the residual interest after creditors are paid." .

fis:HybridSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDebtFeature ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:hasEquityFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "Combines some characteristics of both debt and equity securities, e.g. preference shares, convertibles, equity warrants." .

#################################################################
#  BOND (core)
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon)." .

#################################################################
#  BOND BY ISSUER
#################################################################

fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "treasury bond" ;
  rdfs:comment "Issued by a sovereign national government." .
fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a supranational organisation such as the World Bank." .
fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a local authority or subdivision within a country." .
fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a corporation; excludes bonds of local authorities." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ; rdfs:comment "UK government bond." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
[] a owl:AllDisjointClasses ; owl:members ( fis:ConventionalGilt fis:IndexLinkedGilt ) .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with the longest maturity (20-30 years)." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Secured by the full faith and credit of the issuer's taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repaid solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments; a form of general obligation bond." .
fis:BuildAmericaBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:label "junk bond" ;
  rdfs:comment "Rated below investment grade by credit rating agencies." .
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:label "high grade bond" .
[] a owl:AllDisjointClasses ; owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) .

fis:MortgageBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:comment "Secured by the pledge of specific real estate assets." .
fis:CollateralTrustBond a owl:Class ; rdfs:subClassOf fis:CorporateBond .
fis:EquipmentTrustCertificate a owl:Class ; rdfs:subClassOf fis:CorporateBond .
fis:DebentureBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
  rdfs:comment "Unsecured debenture; long maturity, typically at least ten years." .
fis:GuaranteedBond a owl:Class ; rdfs:subClassOf fis:CorporateBond .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a government or corporate entity to raise finance for climate change mitigation or adaptation." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .

#################################################################
#  BOND BY MATURITY
#################################################################

fis:ShortTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:MediumTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:LongTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "perpetuity" ; rdfs:comment "Has no maturity date; principal repaid only at the discretion of the borrower, if at all." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond fis:PerpetualBond ) .

fis:Methuselah a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond with a maturity of 50 years or longer." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

#################################################################
#  BOND BY COUPON TYPE
#################################################################

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon is linked to a reference rate and recalculated periodically." .
fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par, full principal paid at maturity." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

fis:SteppedCouponBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "Coupon increases during the life of the bond." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "Issuer redeems randomly selected individual bonds within the issue, some at above face value." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "index-linked bond" ;
  rdfs:comment "Principal amount and interest payments are indexed to the level of consumer prices." .
fis:StripBond a owl:Class ; rdfs:subClassOf fis:ZeroCouponBond ;
  rdfs:comment "Created by separating ('stripping') the coupons from the principal of a fixed rate bond." .

#################################################################
#  BOND BY EMBEDDED OPTION
#################################################################

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
  rdfs:comment "Gives the issuer the right to repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
  rdfs:label "retractable bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity." .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CallableBond fis:PutableBond fis:BulletBond ) .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasDebtFeature ; owl:hasValue true ] ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasEquityFeature ; owl:hasValue true ] ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "A bond that the holder can convert into a specified number of shares of common stock in the issuing company; a hybrid security." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .
fis:ConvertibleDebenture a owl:Class ; rdfs:subClassOf fis:DebentureBond, fis:ConvertibleBond .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:PackagedConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "A 'bond + option' structure: a straight bond and a call option/warrant wrapped together, tradeable as separate legs." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity; settled in cash, no equities produced." .
fis:ReverseConvertibleBond a owl:Class ; rdfs:subClassOf fis:SyntheticConvertibleBond ;
  rdfs:comment "A variation of a mandatory convertible bearing a contingent conversion feature; most reverse convertibles are synthetic." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:PackagedConvertibleBond fis:SyntheticConvertibleBond ) .

#################################################################
#  BOND BY FORM (derived from Security forms)
#################################################################

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

#################################################################
#  EURO DEBT SECURITIES
#################################################################

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Issued internationally outside the domestic market of the issuer, in a denomination different from the issuer's domicile." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:Bond ;
  rdfs:comment "Characteristically underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity .

#################################################################
#  MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short term debt instrument, highly liquid, with original maturity of one year or less." .

fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:GovernmentBond, fis:ZeroCouponBond ;
  rdfs:comment "Zero-coupon government debt obligation maturing in one year or less." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Unsecured promissory note with a fixed maturity of usually less than 270 days." .
fis:AssetBackedCommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper .
fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper, fis:Euronote .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Time deposit commonly offered to consumers by banks, thrift institutions and credit unions." .
fis:JumboCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit, fis:BearerSecurity ;
  rdfs:comment "Negotiable certificate of deposit with minimum deposit of $100,000, issued in bearer form." .
fis:EuroCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit, fis:Euronote .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:FederalFundsInstrument a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:TreasuryBill fis:CommercialPaper fis:CertificateOfDeposit
                fis:BankersAcceptance fis:RepurchaseAgreement fis:MunicipalNote fis:FederalFundsInstrument ) .

#################################################################
#  ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from a pool of other assets." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet." ;
  owl:disjointWith fis:AssetBackedSecurity .

fis:MortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "MBS" ; rdfs:comment "Secured by a mortgage or a pool of mortgages." .
fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "CDO" ; rdfs:comment "Structured ABS sliced into tranches catching cash flow in sequence based on seniority." .
fis:SquaredCollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:CollateralizedDebtObligation ;
  rdfs:label "CDO-squared" .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Issued by a trust; allocates cash flows from the underlying pool to holders on a pro rata basis." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "pay-through bond" ;
  rdfs:comment "A debt obligation of a legal entity collateralized by the assets it owns, divided into classes with differing maturities and payment priority." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:comment "Re-securitized residual interest of a mortgage-backed security." .
[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity, fis:PassThroughSecurity ;
  rdfs:label "RMBS" ; rdfs:comment "Secured by single-family, one- to four-unit residential real estate." .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity, fis:PassThroughSecurity ;
  rdfs:label "CMBS" ; rdfs:comment "Secured by commercial and multi-family properties." .
[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:StudentLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ; rdfs:label "SLABS" .
fis:AutoLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:CreditCardAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:HomeEquityLoanAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:StudentLoanAssetBackedSecurity fis:AutoLoanAssetBackedSecurity
                fis:CreditCardAssetBackedSecurity fis:HomeEquityLoanAssetBackedSecurity
                fis:MortgageBackedSecurity fis:CollateralizedDebtObligation ) .

fis:Tranche a owl:Class ;
  rdfs:comment "A slice of a structured security (e.g. CDO, MBS) with a given seniority and risk/reward level." .

#################################################################
#  EQUITY: STOCK
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:EquitySecurity, fis:UndividedSecurity ;
  rdfs:comment "All the shares by which ownership of a corporation or company is divided." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "ordinary share" ;
  rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "preference share" ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasDebtFeature ; owl:hasValue true ] ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasEquityFeature ; owl:hasValue true ] ;
  rdfs:comment "A component of share capital with any combination of features not possessed by common stock; generally considered a hybrid instrument; senior to common stock but subordinate to bonds." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate as 'dividends in arrears' until paid." .
fis:NonCumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "straight preferred stock" ;
  rdfs:comment "Any passed dividends are lost if not declared." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Preferred stock convertible into a fixed number of common shares." .
fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Carries a call provision enabling the issuer to repurchase the share at its discretion." .
fis:PerpetualPreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock .

fis:RestrictedSecurity a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "Rule 144 stock acquired in unregistered form from the issuing company." .
fis:ControlSecurity a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "Rule 144 stock acquired in unregistered form from an affiliate of the issuer." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RestrictedSecurity fis:ControlSecurity ) .

#################################################################
#  DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "A negotiable financial instrument issued by a bank representing a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "GDR" .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
#  DERIVATIVES
#################################################################

fis:Forward a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Tailored, non-standardized contract between two parties with payment at a specific future time at today's pre-determined price." .
fis:Future a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .
fis:Option a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Gives the owner the right, but not the obligation, to buy or sell an underlying asset at a strike price on or before a maturity date." .
fis:Swap a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) .

fis:ForwardRateAgreement a owl:Class ; rdfs:subClassOf fis:Forward ; rdfs:label "FRA" .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The right, not the obligation, to buy an asset at a fixed (strike) price." .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The right, not the obligation, to sell an asset at a fixed (strike) price." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset time period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a certain barrier before the option can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing option that pays the full amount if the condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasDebtFeature ; owl:hasValue true ] ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasEquityFeature ; owl:hasValue true ] ;
  rdfs:comment "A long-dated option issued by the company itself allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "CDS" ;
  rdfs:comment "Seller compensates the buyer (creditor of a reference loan) in the event of a loan default or other credit event, in return for periodic premium payments." .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap ) .

fis:BasketDefaultSwap a owl:Class ; rdfs:subClassOf fis:CreditDefaultSwap ; rdfs:label "BDS" .
fis:IndexCreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:CreditDefaultSwap .
fis:CreditLinkedNote a owl:Class ; rdfs:subClassOf fis:CreditDefaultSwap, fis:DebtSecurity ;
  rdfs:label "funded CDS" .
fis:LoanOnlyCreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:CreditDefaultSwap ; rdfs:label "LCDS" .

#################################################################
#  STOCK DERIVATIVES
#################################################################

fis:StockDerivative a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." .

fis:StockFuture a owl:Class ; rdfs:subClassOf fis:Future, fis:StockDerivative .
fis:SingleStockFuture a owl:Class ; rdfs:subClassOf fis:StockFuture .
fis:StockIndexFuture a owl:Class ; rdfs:subClassOf fis:StockFuture ;
  rdfs:comment "Generally delivered by cash settlement." .
fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option, fis:StockDerivative .

#################################################################
#  FUNDS
#################################################################

fis:Fund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "An investment fund that pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "SEC-registered open-end investment company that pools money to invest in stocks, bonds, money-market instruments or other securities." .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Shares purchased from or sold to the issuer at the next calculated net asset value." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
[] a owl:AllDisjointClasses ; owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Invests in liquid, short-term debt securities, cash and cash equivalents." .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:label "income fund" .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:label "stock fund" .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
[] a owl:AllDisjointClasses ; owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "A passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:Fund .
[] a owl:AllDisjointClasses ; owl:members ( fis:IndexFund fis:ActivelyManagedFund ) .

fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "ETF" ;
  rdfs:comment "Shares trade on national securities exchanges at market prices that may differ from net asset value, unlike mutual fund shares." .
fis:IndexExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund, fis:IndexFund .
fis:InverseExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ; rdfs:label "IETF" .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ; rdfs:label "LETF" .
[] a owl:AllDisjointClasses ; owl:members ( fis:InverseExchangeTradedFund fis:LeveragedExchangeTradedFund ) .

fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Pools money from investors like a mutual fund but has fewer regulations protecting investors and uses riskier, more flexible strategies." .

#################################################################
#  DIVIDEND
#################################################################

fis:Dividend a owl:Class ; rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, not a contractual obligation." .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
[] a owl:AllDisjointClasses ; owl:members ( fis:CashDividend fis:StockDividend ) .

#################################################################
#  ISSUERS, HOLDERS, INVESTORS
#################################################################

fis:Issuer a owl:Class ; rdfs:comment "The company or other entity issuing a security." .

fis:Holder a owl:Class ; rdfs:comment "The person or entity holding a security." .

fis:Shareholder a owl:Class ;
  rdfs:label "stockholder" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:Bondholder a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Bond ] ) ] .

fis:Investor a owl:Class ; rdfs:subClassOf fis:Holder .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "A member of the public investing personally, other than by way of business." .
fis:WholesaleInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "A financial institution acting on its own account or on behalf of clients." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:WholesaleInvestor ) .

fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:WholesaleInvestor ;
  rdfs:comment "Includes investment banks, insurance companies, pension funds and other managed funds." .

#################################################################
#  COLLATERAL AND SECURITIES-BASED LENDING
#################################################################

fis:CollateralArrangement a owl:Class ;
  rdfs:comment "An arrangement whereby property rights in securities are delivered to a creditor, at inception or in default." .
fis:SecurityInterest a owl:Class ; rdfs:subClassOf fis:CollateralArrangement ;
  rdfs:comment "Non-transfer-of-title institutional arrangement; property rights not transferred but enable satisfaction of claims in default." .
fis:OutrightCollateralTransfer a owl:Class ; rdfs:subClassOf fis:CollateralArrangement ;
  rdfs:comment "Transfer of title in collateral at inception." .
[] a owl:AllDisjointClasses ; owl:members ( fis:SecurityInterest fis:OutrightCollateralTransfer ) .

fis:SecuritiesBasedLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:StandardInstitutionalLoan a owl:Class ; rdfs:subClassOf fis:SecuritiesBasedLoan ;
  rdfs:comment "Low loan-to-value with strict call and coverage regimens, akin to standard margin loans." .
fis:TransferOfTitleLoan a owl:Class ; rdfs:subClassOf fis:SecuritiesBasedLoan ;
  rdfs:label "ToT loan" ;
  rdfs:comment "Borrower ownership is completely extinguished save for rights provided in the loan contract." .
fis:NonTransferOfTitleCreditLine a owl:Class ; rdfs:subClassOf fis:SecuritiesBasedLoan ;
  rdfs:comment "Shares are not sold and serve as assets in a standard lien-type line of cash credit." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:StandardInstitutionalLoan fis:TransferOfTitleLoan fis:NonTransferOfTitleCreditLine ) .
